function wordMap(rows, lang, name) {
  var map = {};
  var list = Array.isArray(rows) ? rows : [];
  for (var i = 0; i < list.length; i++) if (list[i] && list[i].key) map[list[i].key] = String(list[i][lang] || list[i].en || '').split('{b}').join(name);
  return map;
}
function fill(text, vars) { var t = String(text || ''); for (var k in vars) t = t.split('{' + k + '}').join(String(vars[k])); return t; }
function langOf(v) { return String(v) === 'fr' ? 'fr' : 'en'; }
function nameOf(v) { var n = String(v || '').trim(); return n || 'Pip'; }

var ORDER = ["say-thanks","name-one","name-three","words-to-blocks","count-in-words","what-wants","is-it-a","count-tulips","maths-seeds","maths","no-letter-e","tall-tales","translate","poem","explain-program","narrate-run","name-trick","sort-words","define","letter"];
var BAND = {"say-thanks":2,"name-one":2,"name-three":2,"words-to-blocks":2,"count-in-words":2,"what-wants":2,"is-it-a":2,"count-tulips":2,"maths-seeds":2,"maths":2,"no-letter-e":2,"tall-tales":2,"translate":2,"poem":2,"explain-program":2,"narrate-run":2,"name-trick":2,"sort-words":2,"define":2,"letter":2};
var TITLE = {"say-thanks":"rungSayThanks","name-one":"rungNameOne","name-three":"rungNameThree","words-to-blocks":"rungWordsToBlocks","count-in-words":"rungCountInWords","what-wants":"rungWhatWants","is-it-a":"rungIsItA","count-tulips":"rungCountTulips","maths-seeds":"rungMathsSeeds","maths":"rungMaths","no-letter-e":"rungNoLetterE","tall-tales":"rungTallTales","translate":"rungTranslate","poem":"rungPoem","explain-program":"rungExplainProgram","narrate-run":"rungNarrateRun","name-trick":"rungNameTrick","sort-words":"rungSortWords","define":"rungDefine","letter":"rungLetter"};
var lang = langOf(Inputs.lang), band = Number(Inputs.band) === 1 ? 1 : 2;
var w = wordMap(Inputs.words, lang, nameOf(Inputs.botName));
var rungs = Inputs.exam && Inputs.exam.rungs && typeof Inputs.exam.rungs === 'object' ? Inputs.exam.rungs : {};
var held = [];
for (var i = 0; i < ORDER.length; i++) { var id = ORDER[i]; if (BAND[id] <= band && rungs[id] && rungs[id].pass === false) held.push(id); }
var names = [];
for (var j = 0; j < held.length; j++) names.push(w[TITLE[held[j]]] || held[j]);
Outputs.held = held;
Outputs.show = held.length > 0;
Outputs.text = held.length ? (w.oliveCant || '') + (lang === 'fr' ? ' : ' : ': ') + names.join(', ') : '';
